local CardDeckMaker = {}
local PRODUCTS = {
    parchment_deck = { name = "Pergamentni karte", parchmentCost = 2, inkCost = 1, time = 2, cost = 18, artistry = 40, happiness = 2, description = "Pergamentni karte za preproste igre." },
    painted_deck = { name = "Poslikani karte", parchmentCost = 2, inkCost = 1, paintCost = 1, time = 3, cost = 45, artistry = 55, prestige = 2, happiness = 3, description = "Poslikani karte z barvnimi motivi." },
    gilded_deck = { name = "Pozlačene karte", parchmentCost = 2, inkCost = 1, goldCost = 1, paintCost = 1, time = 5, cost = 110, artistry = 70, prestige = 5, happiness = 4, description = "Pozlačene karte za plemiče." },
    silver_trim_deck = { name = "Srebrno obrobljene karte", parchmentCost = 2, silverCost = 1, goldCost = 1, inkCost = 1, paintCost = 1, time = 7, cost = 260, artistry = 82, prestige = 10, happiness = 5, description = "Srebrno obrobljene karte za dvorno modo." },
    gold_leaf_deck = { name = "Zlatolistne karte", parchmentCost = 3, goldCost = 1, silverCost = 1, jewelCost = 1, inkCost = 1, paintCost = 1, time = 10, cost = 560, artistry = 92, prestige = 18, happiness = 7, description = "Zlatolistne karte za visoke plemiče." },
    royal_grand_deck = { name = "Kraljevski veliki karte", parchmentCost = 4, goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, inkCost = 2, paintCost = 2, time = 15, cost = 1500, artistry = 100, prestige = 38, happiness = 12, description = "Velike kraljevske karte z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Kartarska delavnica", cost = { gold = 250, wood = 120, stone = 200 }, upkeep = 6, qualityBonus = 5 },
    painting_room = { name = "Slikalnica", cost = { gold = 850, wood = 220, stone = 400, ink = 8 }, upkeep = 21, qualityBonus = 18 },
    gilding_room = { name = "Pozlatnica", cost = { gold = 2200, wood = 350, stone = 600, silver = 25, gold = 6 }, upkeep = 55, qualityBonus = 30 },
    royal_card_atelier = { name = "Kraljevski atelje kart", cost = { gold = 9000, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 40 },
}
CardDeckMaker.parchmentStock = 18; CardDeckMaker.inkStock = 14; CardDeckMaker.paintStock = 12; CardDeckMaker.silverStock = 8; CardDeckMaker.goldStock = 6; CardDeckMaker.jewelStock = 6; CardDeckMaker.pearlStock = 4
CardDeckMaker.productStock = {}; CardDeckMaker.buildings = {}; CardDeckMaker.maker = nil; CardDeckMaker.activeMaking = {}; CardDeckMaker.totalProducts = 0; CardDeckMaker.dayTimer = 0
function CardDeckMaker.init() CardDeckMaker.parchmentStock=18; CardDeckMaker.inkStock=14; CardDeckMaker.paintStock=12; CardDeckMaker.silverStock=8; CardDeckMaker.goldStock=6; CardDeckMaker.jewelStock=6; CardDeckMaker.pearlStock=4; CardDeckMaker.productStock={}; CardDeckMaker.buildings={}; CardDeckMaker.maker=nil; CardDeckMaker.activeMaking={}; CardDeckMaker.totalProducts=0; CardDeckMaker.dayTimer=0; print("[CardDeckMaker] Royal Card Deck Maker System initialized (6 products, 4 buildings)") end
function CardDeckMaker.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CardDeckMaker.maker={name=n or ("Kartar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kartar najet: %s (spretnost: %d)",CardDeckMaker.maker.name,s),"success") end; return true end
function CardDeckMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CardDeckMaker.build(id) local ok,e=CardDeckMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CardDeckMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CardDeckMaker.getQualityBonus() local b=0; for _,bd in ipairs(CardDeckMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CardDeckMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.parchmentCost and CardDeckMaker.parchmentStock<(d.parchmentCost or 0) then return false,"Premalo pergamenta" end; if d.inkCost and CardDeckMaker.inkStock<(d.inkCost or 0) then return false,"Premalo črnila" end; if d.paintCost and CardDeckMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.silverCost and CardDeckMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CardDeckMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CardDeckMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CardDeckMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CardDeckMaker.buildings==0 then return false,"Potrebna delavnica" end; if not CardDeckMaker.maker then return false,"Potreben kartar" end; return true end
function CardDeckMaker.make(pt,qty) qty=qty or 1; local ok,e=CardDeckMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.parchmentCost then CardDeckMaker.parchmentStock=CardDeckMaker.parchmentStock-d.parchmentCost*qty end; if d.inkCost then CardDeckMaker.inkStock=CardDeckMaker.inkStock-d.inkCost*qty end; if d.paintCost then CardDeckMaker.paintStock=CardDeckMaker.paintStock-d.paintCost*qty end; if d.silverCost then CardDeckMaker.silverStock=CardDeckMaker.silverStock-d.silverCost*qty end; if d.goldCost then CardDeckMaker.goldStock=CardDeckMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CardDeckMaker.jewelStock=CardDeckMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CardDeckMaker.pearlStock=CardDeckMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CardDeckMaker.maker then t=math.max(1,t-math.floor(CardDeckMaker.maker.skill/12)) end; table.insert(CardDeckMaker.activeMaking,{id="carddeck_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,artistry=d.artistry or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CardDeckMaker.completeMaking(m) local q=1.0+(CardDeckMaker.getQualityBonus()/100); if CardDeckMaker.maker then q=q+(CardDeckMaker.maker.skill/180) end; q=math.min(2.0,q); CardDeckMaker.productStock[m.productType]=(CardDeckMaker.productStock[m.productType] or 0)+m.quantity; CardDeckMaker.totalProducts=CardDeckMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CardDeckMaker.maker then CardDeckMaker.maker.itemsMade=CardDeckMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then CardDeckMaker.maker.skill=math.min(100,CardDeckMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Karte izdelane: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"carddeck.completed",{productName=m.productName,artistry=m.artistry,prestige=m.prestige,happiness=m.happiness}) end end
function CardDeckMaker.update(dt) if not _G.state then return end; CardDeckMaker.dayTimer=CardDeckMaker.dayTimer+dt; if CardDeckMaker.dayTimer>=30 then CardDeckMaker.dayTimer=0; for i=#CardDeckMaker.activeMaking,1,-1 do local m=CardDeckMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CardDeckMaker.completeMaking(m); table.remove(CardDeckMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CardDeckMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CardDeckMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CardDeckMaker.getStats() return {parchmentStock=CardDeckMaker.parchmentStock,inkStock=CardDeckMaker.inkStock,paintStock=CardDeckMaker.paintStock,silverStock=CardDeckMaker.silverStock,goldStock=CardDeckMaker.goldStock,jewelStock=CardDeckMaker.jewelStock,pearlStock=CardDeckMaker.pearlStock,productStock=CardDeckMaker.productStock,numBuildings=#CardDeckMaker.buildings,hasMaker=CardDeckMaker.maker~=nil,makerName=CardDeckMaker.maker and CardDeckMaker.maker.name or "—",makerSkill=CardDeckMaker.maker and CardDeckMaker.maker.skill or 0,activeMaking=#CardDeckMaker.activeMaking,totalProducts=CardDeckMaker.totalProducts} end
return CardDeckMaker
